-- Generated by scripts/gen-staff-scope.py from src/lib/catalog.ts.
-- Regenerate after changing FULL_ACCESS_ROLES, STAFF_SHARED_RESOURCES or
-- STAFF_DEPARTMENTS; do not edit the generated arrays by hand.

-- ---------------------------------------------------------------------------
-- 1. Additive columns and tables: staff-to-employee assignment, document
--    folders, and folder keys on attachments. Nothing existing is altered.
-- ---------------------------------------------------------------------------
alter table public.memberships
  add column if not exists staff_employee_id text;
create index if not exists memberships_staff_employee_idx
  on public.memberships(organization_id, staff_employee_id)
  where staff_employee_id is not null;

alter table public.attachments
  add column if not exists folder_key text;
create index if not exists attachments_org_folder_idx
  on public.attachments(organization_id, folder_key)
  where folder_key is not null;

create index if not exists records_ref_assigned_to_idx
  on public.records(organization_id, resource, ((data->>'assignedTo'))) where deleted_at is null;
create index if not exists records_ref_crew_leader_idx
  on public.records(organization_id, resource, ((data->>'crewLeader'))) where deleted_at is null;

create table if not exists public.document_folders (
  id              uuid primary key default extensions.gen_random_uuid(),
  organization_id uuid not null references public.organizations(id) on delete cascade,
  name            text not null,
  parent_key      text,
  project_id      text,
  created_by_id   uuid references auth.users(id) on delete set null,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);
create index if not exists document_folders_org_idx on public.document_folders(organization_id, project_id);
create index if not exists document_folders_parent_idx on public.document_folders(organization_id, parent_key);
alter table public.document_folders enable row level security;

-- ---------------------------------------------------------------------------
-- 2. Staff scope helpers. SECURITY DEFINER is deliberate: these run while
--    Postgres is evaluating a policy on public.records, so they must read the
--    register without re-entering that same policy.
-- ---------------------------------------------------------------------------
create or replace function public.app_full_access(p_role text) returns boolean
language sql immutable set search_path = public, pg_temp as $$
  select p_role = any(array['OWNER','ADMIN']::text[]);
$$;

create or replace function public.app_staff_shared_resources() returns text[]
language sql immutable set search_path = public, pg_temp as $$
  select array['clients','contacts','vendors','subcontractors','departments','crews','warehouses','accounts']::text[];
$$;

create or replace function public.app_staff_departments(p_role text) returns text[]
language sql immutable set search_path = public, pg_temp as $$
  select case p_role
    when 'OWNER' then array[]::text[]
    when 'ADMIN' then array[]::text[]
    when 'PROJECT_MANAGER' then array['leads','estimates','bids']::text[]
    when 'SITE_ENGINEER' then array[]::text[]
    when 'FINANCE_MANAGER' then array['accounts','journals','payRuns','expenses','leaveRequests','arInvoices','apBills','payments','paymentApps','budgets']::text[]
    when 'ACCOUNTANT' then array['accounts','journals','payRuns','expenses','arInvoices','apBills','payments','paymentApps','budgets']::text[]
    when 'HR_MANAGER' then array['employees','departments','crews','leaveRequests','payRuns','certifications','training','timesheets']::text[]
    when 'PROCUREMENT' then array['vendors','subcontractors','requisitions','purchaseOrders','goodsReceipts','inventory','warehouses']::text[]
    when 'SAFETY_OFFICER' then array['toolboxTalks','incidents','inspections','ncrs','itps','permits','certifications','training']::text[]
    when 'PLANT_MANAGER' then array['equipment','workOrders','inventory','warehouses']::text[]
    when 'ESTIMATOR' then array['leads','estimates','bids','clients','contacts']::text[]
    when 'VIEWER' then array[]::text[]
    when 'CLIENT_EXTERNAL' then array[]::text[]
    when 'SUBCONTRACTOR_EXTERNAL' then array[]::text[]
    else array[]::text[]
  end;
$$;

create or replace function public.app_employee(p_org uuid) returns text
language sql stable security definer set search_path = public, pg_temp as $$
  select staff_employee_id from public.memberships
  where user_id = auth.uid() and organization_id = p_org limit 1;
$$;

-- Jobs assigned to the signed-in member: projects they manage, tasks assigned
-- to them, their time sheets and crews they lead. Stable + constant arg lets
-- Postgres evaluate this once per statement instead of once per row.
create or replace function public.app_staff_project_ids(p_org uuid) returns text[]
language sql stable security definer set search_path = public, pg_temp as $$
  with e as (select public.app_employee(p_org) as emp),
  ids as (
    select r.id as pid from public.records r, e
     where r.organization_id = p_org and r.resource = 'projects'
       and r.deleted_at is null and e.emp is not null
       and r.data->>'manager' = e.emp
    union
    select r.project_id from public.records r, e
     where r.organization_id = p_org and r.resource = 'tasks'
       and r.deleted_at is null and e.emp is not null
       and r.data->>'assignedTo' = e.emp and r.project_id is not null
    union
    select r.project_id from public.records r, e
     where r.organization_id = p_org and r.resource = 'timesheets'
       and r.deleted_at is null and e.emp is not null
       and r.data->>'employeeId' = e.emp and r.project_id is not null
    union
    select r.project_id from public.records r, e
     where r.organization_id = p_org and r.resource = 'crews'
       and r.deleted_at is null and e.emp is not null
       and r.data->>'crewLeader' = e.emp and r.project_id is not null
  )
  select coalesce(array_agg(distinct pid), array[]::text[]) from ids where pid is not null;
$$;

create or replace function public.app_staff_client_ids(p_org uuid) returns text[]
language sql stable security definer set search_path = public, pg_temp as $$
  select coalesce(array_agg(distinct r.data->>'clientId'), array[]::text[])
    from public.records r
   where r.organization_id = p_org and r.resource = 'projects'
     and r.deleted_at is null and r.data->>'clientId' is not null
     and r.id = any(public.app_staff_project_ids(p_org));
$$;

-- ---------------------------------------------------------------------------
-- 3. Row visibility. External portal rules are unchanged; internal staff now
--    see shared master data, their department, their own staff record and the
--    records on jobs assigned to them. Owners/admins keep the whole workspace.
-- ---------------------------------------------------------------------------
create or replace function public.app_visible_record(
  p_org uuid, p_resource text, p_id text, p_project_id text, p_data jsonb
)
returns boolean language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  r text; e text; emp text; pids text[]; d jsonb;
begin
  if p_org is null or p_id is null then return false; end if;
  r := public.app_role(p_org);
  if r is null then return false; end if;
  if public.app_full_access(r) then return true; end if;
  e := public.app_entity(p_org);
  d := coalesce(p_data, '{}'::jsonb);

  if r = 'CLIENT_EXTERNAL' then
    if e is null then return false; end if;
    if p_resource = 'clients' then return p_id = e; end if;
    if p_resource = 'contacts' then return d->>'clientId' = e; end if;
    select coalesce(array_remove(array_agg(id), null), array[]::text[]) into pids
      from public.records
      where organization_id = p_org and resource = 'projects' and deleted_at is null
        and data->>'clientId' = e;
    if p_resource = 'projects' then return p_id = any(pids); end if;
    if d->>'clientId' = e then return true; end if;
    if p_project_id is not null and p_project_id = any(pids) then return true; end if;
    return false;
  end if;

  if r = 'SUBCONTRACTOR_EXTERNAL' then
    if e is null then return false; end if;
    if p_resource = 'subcontractors' then return p_id = e; end if;
    select coalesce(array_remove(array_agg(project_id), null), array[]::text[]) into pids
      from public.records
      where organization_id = p_org and resource in ('contracts','submittals') and deleted_at is null
        and (data->>'counterparty' = e or data->>'submittedBy' = e or data->>'subcontractorId' = e);
    if p_resource = 'projects' then return p_id = any(pids); end if;
    if d->>'counterparty' = e or d->>'submittedBy' = e or d->>'subcontractorId' = e then return true; end if;
    if p_project_id is not null and p_project_id = any(pids) then return true; end if;
    return false;
  end if;

  -- Internal staff
  emp := public.app_employee(p_org);
  if p_resource = any(public.app_staff_shared_resources()) then return true; end if;
  if p_resource = any(public.app_staff_departments(r)) then return true; end if;
  if p_resource = 'employees' and emp is not null and p_id = emp then return true; end if;
  -- A manager may create a new job they will run; it becomes visible as soon
  -- as it is saved because app_staff_project_ids reads the manager field.
  if p_resource = 'projects' and emp is not null and d->>'manager' = emp then return true; end if;
  pids := public.app_staff_project_ids(p_org);
  if p_resource = 'projects' then return p_id = any(pids); end if;
  if p_project_id is not null and p_project_id = any(pids) then return true; end if;
  return false;
end;
$$;

create or replace function public.app_wallet_client_allowed(p_org uuid, p_client_id text)
returns boolean language plpgsql stable security definer set search_path = public, pg_temp as $$
declare r text; pids text[]; cids text[];
begin
  if p_org is null or p_client_id is null or not (p_org = any(public.app_org_ids())) then return false; end if;
  r := public.app_role(p_org);
  if r is null then return false; end if;
  if public.app_full_access(r) then return true; end if;
  if r = 'CLIENT_EXTERNAL' then return public.app_entity(p_org) = p_client_id; end if;
  if r = 'SUBCONTRACTOR_EXTERNAL' then return false; end if;
  -- Only owners/admins see the whole company. Staff without an assigned job
  -- have no client wallets; assigned staff see clients on their own jobs.
  pids := public.app_staff_project_ids(p_org);
  if coalesce(array_length(pids, 1), 0) = 0 then return false; end if;
  cids := public.app_staff_client_ids(p_org);
  return p_client_id = any(cids);
end;
$$;

-- ---------------------------------------------------------------------------
-- 4. Folder RLS. A folder belongs to a job; a member may browse folders for
--    jobs they can already see. Creating/renaming needs attach rights.
-- ---------------------------------------------------------------------------
drop policy if exists document_folders_select on public.document_folders;
create policy document_folders_select on public.document_folders for select to authenticated
  using (
    organization_id = any(public.app_org_ids())
    and public.app_can_read(organization_id, 'documents')
    and (project_id is null or public.app_visible_record_id(organization_id, project_id))
  );

drop policy if exists document_folders_insert on public.document_folders;
create policy document_folders_insert on public.document_folders for insert to authenticated
  with check (
    organization_id = any(public.app_org_ids())
    and public.app_can_write(organization_id, 'documents')
    and public.app_has_capability(organization_id, 'files.upload')
    and (project_id is null or public.app_visible_record_id(organization_id, project_id))
  );

drop policy if exists document_folders_update on public.document_folders;
create policy document_folders_update on public.document_folders for update to authenticated
  using (
    organization_id = any(public.app_org_ids())
    and public.app_can_write(organization_id, 'documents')
    and public.app_has_capability(organization_id, 'files.upload')
    and (project_id is null or public.app_visible_record_id(organization_id, project_id))
  )
  with check (
    organization_id = any(public.app_org_ids())
    and public.app_can_write(organization_id, 'documents')
    and public.app_has_capability(organization_id, 'files.upload')
    and (project_id is null or public.app_visible_record_id(organization_id, project_id))
  );

drop policy if exists document_folders_delete on public.document_folders;
create policy document_folders_delete on public.document_folders for delete to authenticated
  using (
    organization_id = any(public.app_org_ids())
    and public.app_can_delete(organization_id, 'documents')
    and public.app_has_capability(organization_id, 'files.delete')
    and (project_id is null or public.app_visible_record_id(organization_id, project_id))
  );

-- Internal staff should not read company-wide activity about jobs they cannot
-- see; owner/admin keep the full audit trail.
drop policy if exists audit_logs_select on public.audit_logs;
create policy audit_logs_select on public.audit_logs for select to authenticated
  using (
    organization_id = any(public.app_org_ids())
    and (public.app_full_access(public.app_role(organization_id)) or user_id = auth.uid())
  );

grant select, insert, update, delete on public.document_folders to authenticated, service_role;
grant execute on function public.app_full_access(text) to authenticated, service_role;
grant execute on function public.app_staff_shared_resources() to authenticated, service_role;
grant execute on function public.app_staff_departments(text) to authenticated, service_role;
grant execute on function public.app_employee(uuid) to authenticated, service_role;
grant execute on function public.app_staff_project_ids(uuid) to authenticated, service_role;
grant execute on function public.app_staff_client_ids(uuid) to authenticated, service_role;
